## docker-compose.yml
```yaml
version: '3.8'

services:
  app:
    build: 
      context: .
      dockerfile: Dockerfile
    container_name: express-app
    ports:
      - "8000:8000"
    environment:
      - NODE_ENV=production
    restart: unless-stopped
    volumes:
      - app-data:/app/data

volumes:
  app-data:
```

## Dockerfile
```dockerfile
FROM node:18-alpine

WORKDIR /app

# Copy package files and install dependencies
COPY package*.json ./
RUN npm install --production

# Copy application code
COPY . .

# Expose the application port
EXPOSE 8000

# Set environment variables
ENV NODE_ENV=production

# Command to run the application
CMD ["npm", "start"]
```

## Dockerfile.multistage
```dockerfile
# Stage 1: Development/Build stage
FROM node:18-alpine AS builder

WORKDIR /app

# Copy package files
COPY package*.json ./

# Install ALL dependencies (including dev dependencies)
RUN npm install

# Copy application code
COPY . .

# Run any build steps if needed (not required for this simple app)
# RUN npm run build

# Stage 2: Production stage
FROM node:18-alpine AS final

WORKDIR /app

# Copy package files
COPY package*.json ./

# Install ONLY production dependencies
RUN npm install --production

# Copy application code from builder stage
COPY --from=builder /app/app.js ./

# Expose the application port
EXPOSE 8000

# Set environment variables
ENV NODE_ENV=production

# Command to run the application
CMD ["npm", "start"]
```

## Makefile
```makefile
# =======================================================
# SIMPLIFIED DOCKER MAKEFILE
# =======================================================
# This Makefile focuses on Docker operations for Express server

# =======================================================
# DOCKER VARIABLES
# =======================================================
# Default values that can be overridden from command line
# e.g., make build IMG=express-server TAG=v2.0

IMG ?= express-server
TAG ?= v1.1
USER ?= myuser
NAME ?= express-app
REGISTRY ?= myregistry.com

# =======================================================
# BASIC DOCKER COMMANDS
# =======================================================

# Build a Docker image
build:
	docker build -t ${USER}/${IMG}:${TAG} .
	@echo "Built Docker image: ${USER}/${IMG}:${TAG}"

# Run the Docker container (requires build first)
run: build
	docker run --name ${NAME} -d -p 8000:8000 ${USER}/${IMG}:${TAG}
	@echo "Started container: ${NAME}"

# Stop and remove the container
stop:
	docker stop ${NAME}
	docker rm ${NAME}
	@echo "Stopped and removed container: ${NAME}"

# =======================================================
# MULTI-STAGE DOCKER BUILDS
# =======================================================

# Build with multi-stage Dockerfile
build-ms:
	docker build -f Dockerfile.multistage -t ${USER}/${IMG}:${TAG} .
	@echo "Built multi-stage Docker image: ${USER}/${IMG}:${TAG}"

# Run the multi-stage container (requires build-ms first)
run-ms: build-ms
	docker run --name ${NAME}-ms -d -p 8001:8000 ${USER}/${IMG}:${TAG}
	@echo "Started multi-stage container: ${NAME}-ms"

# Stop and remove multi-stage container
stop-ms:
	docker stop ${NAME}-ms
	docker rm ${NAME}-ms
	@echo "Stopped and removed multi-stage container"

# =======================================================
# DOCKER COMPOSE COMMANDS
# =======================================================

# Start services with docker-compose
up:
	docker-compose up -d
	@echo "Started all services with docker-compose"

# Stop services
down:
	docker-compose down
	@echo "Stopped all services"

# View logs
logs:
	docker-compose logs -f

# Build and rebuild services
compose-build:
	docker-compose build
	@echo "Built all services defined in docker-compose.yml"

# Prune unused resources
prune:
	@echo "Pruning unused Docker resources..."
	docker system prune -f
	@echo "Pruned unused containers, networks, images and build cache"

# =======================================================
# EXPRESS SERVER COMMANDS
# =======================================================

# Install dependencies
install:
	npm install

# Run Express server locally
dev:
	npm run dev

# =======================================================
# HELP COMMAND
# =======================================================

# Display help when just 'make' is run
help:
	@echo "======================================================"
	@echo "EXPRESS SERVER DOCKER MAKEFILE"
	@echo "======================================================"
	@echo ""
	@echo "EXPRESS SERVER COMMANDS:"
	@echo "  make install               - Install dependencies"
	@echo "  make dev                   - Run Express server locally"
	@echo ""
	@echo "BASIC DOCKER COMMANDS:"
	@echo "  make build                 - Build Docker image"
	@echo "  make run                   - Run Docker container (port 8000) (builds first)"
	@echo "  make stop                  - Stop and remove container"
	@echo ""
	@echo "MULTI-STAGE BUILDS:"
	@echo "  make build-ms              - Build multi-stage Docker image"
	@echo "  make run-ms                - Run multi-stage container (port 8001) (builds first)"
	@echo "  make stop-ms               - Stop and remove multi-stage container"
	@echo ""
	@echo "MULTIPLE SERVICES:"
	@echo "  make build-all             - Build all service images"
	@echo "  make push-all              - Push all images to registry"
	@echo ""
	@echo "DOCKER COMPOSE COMMANDS:"
	@echo "  make up                    - Start services with docker-compose"
	@echo "  make down                  - Stop services"
	@echo "  make logs                  - View logs"
	@echo "  make compose-build         - Build services with docker-compose"
	@echo ""
	@echo "CONTAINER MANAGEMENT:"
	@echo "  make monitor               - Monitor container resource usage"
	@echo "  make backup                - Backup container volumes"
	@echo "  make prune                 - Clean up unused Docker resources"
	@echo ""
	@echo "VARIABLES YOU CAN OVERRIDE:"
	@echo "  IMG=name                   - Docker image name (default: $(IMG))"
	@echo "  TAG=version                - Docker image tag (default: $(TAG))"
	@echo "  USER=username              - Docker username (default: $(USER))"
	@echo "  NAME=containername         - Container name (default: $(NAME))"
	@echo ""
	@echo "EXAMPLE:"
	@echo "  make build IMG=express-api TAG=v1.0 USER=devuser"
```
